class Solution {
public:
    int findCheapestPrice(int n, vector<vector<int>>& flights, int src, int dst, int k) {

        // Creation of Graph
        vector<vector<pair<int, int>>> G(n);
        for(auto &e : flights) {
            int u = e[0], v = e[1], w = e[2];
            G[u].push_back({v, w});
        }

        k++;

        // Cost, CityID, Stops left
        priority_queue<array<int, 3>, vector<array<int, 3>>, greater<>> pq;
        pq.push({0, src, k});

        //Minimum distance
        vector<vector<int>> dist(k + 1, vector<int>(n, INT_MAX));

        for (int i = 0; i <= k; i++) {
            dist[i][src] = 0;
        }

        while (pq.size()) {
            auto [c, u, stop] = pq.top();
            pq.pop();

            if (c > dist[stop][u]) continue;
            if (u == dst) return c;
            if (stop == 0) continue;

            for (auto &[v, w] : G[u]) {
                int newCost = c + w;
                if (dist[stop - 1][v] > newCost) {
                    dist[stop - 1][v] = newCost;
                    pq.push({newCost, v, stop - 1});
                }
            }
        }

        return -1;
    }
};

class Solution {
public:

    int dirs[4][2] = { {0, 1}, {1, 0}, {-1, 0}, {0, -1}};

    int minimumEffortPath(vector<vector<int>>& A) {

        int M = A.size(), N = A[0].size();

        vector<vector<int>> dist(M, vector<int>(N, INT_MAX));
        priority_queue<array<int, 3>, vector<array<int, 3>>, greater<>> pq;
        pq.push({0, 0, 0});
        dist[0][0] = 0;

        while (pq.size()) {
            auto [cost, a, b] = pq.top();
            pq.pop();

            if (cost > dist[a][b]) continue;
            if (a == M - 1 && b == N - 1) return cost;

            for(auto &dir : dirs) {
                int x = a + dir[0];
                int y = b + dir[1];

                if (x < 0 || y < 0 || x >= M || y >= N) continue;

                int newCost = max(cost, abs(A[a][b] - A[x][y]));

                if (newCost < dist[x][y]) {
                    dist[x][y] = newCost;
                    pq.push({newCost, x, y});
                }
            }
        }

        return dist[M - 1][N - 1];
    }
};

